const body = $json.body || {};
const data = body.data || {};
const expectedSessionId = '257386b8-25b7-48f9-ba30-87f659676294';
const workflowVersion = '1.0.0';
const errors = [];

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    errors.push(`${name} es obligatorio`);
  }
}

required(body.sessionId, 'body.sessionId');
required(body.event, 'body.event');
required(data.id, 'body.data.id');
required(data.chatId, 'body.data.chatId');

if (body.sessionId && body.sessionId !== expectedSessionId) {
  errors.push(`Session ID invalido para Convites: ${body.sessionId}`);
}
if (body.event && body.event !== 'message.received') {
  errors.push(`Evento no soportado: ${body.event}`);
}

// Red de seguridad. El webhook ya filtra estos casos, pero si alguno llega hasta
// aca significa que el filtro se rompio, y un fromMe suelto es un loop infinito.
if (data.fromMe === true) errors.push('fromMe=true: el bot se estaria respondiendo a si mismo');
if (data.isGroup === true) errors.push('isGroup=true: no se atienden grupos');
if (data.isStatusBroadcast === true) errors.push('isStatusBroadcast=true: no se atienden estados');

if (errors.length) {
  throw new Error(`Validate Input fallo: ${errors.join(' | ')}`);
}

const text = String(data.body || '').trim();
const messageType = data.type || 'text';

const media = data.media || {};
const hasMedia = messageType !== 'text' && Boolean(media.data);

// En la cola se guarda solo la FICHA del adjunto, nunca el base64: una nota de
// voz pesa cientos de KB y attachments es una columna jsonb. El contenido se
// transcribe antes de encolar y entra como texto.
const attachments = hasMedia
  ? [{ type: messageType, mimetype: media.mimetype || null }]
  : [];

// OpenWA manda epoch en SEGUNDOS, no milisegundos.
const receivedAt = data.timestamp
  ? new Date(Number(data.timestamp) * 1000).toISOString()
  : new Date().toISOString();

// Llave propia y deterministica sobre el message id de WhatsApp.
// No se usa body.idempotencyKey de OpenWA: termina en un uuid cuya estabilidad
// entre reintentos no esta verificada. data.id si es la clave natural del mensaje.
const idempotencyKey = `convites:openwa:inbound:${data.id}`;
const payloadHash = `${data.id}:${text.length}:${attachments.length}`;

const envelope = {
  client: 'convites',
  workflow_version: workflowVersion,
  event: {
    event_id: `openwa:${data.id}`,
    type: 'InboundMessage',
    timestamp: receivedAt,
    source: 'openwa_whatsapp'
  },
  channel: {
    session_id: body.sessionId,
    chat_id: data.chatId,
    message_id: data.id,
    message_type: messageType,
    sender_jid: data.from || null,
    is_lid: data.isLidSender === true,
    push_name: (data.contact && data.contact.pushName) || null,
    direction: 'inbound'
  },
  actor: {
    automation_allowed: true,
    handoff_state: 'ai_active'
  },
  message: {
    text,
    attachments,
    multimedia_text: '',
    combined_text: text
  }
};

return [{
  json: {
    client: 'convites',
    workflow_id: 'intake-openwa-normalize-queue',
    workflow_version: workflowVersion,
    idempotency_key: idempotencyKey,
    payload_hash: payloadHash,
    current_message_id: data.id,
    has_media: hasMedia,
    envelope,
    queue_item: {
      client: 'convites',
      contact_id: data.chatId,
      conversation_id: data.chatId,
      message_id: data.id,
      text,
      attachments,
      received_at: receivedAt,
      sender_jid: data.from || null,
      is_lid: data.isLidSender === true,
      push_name: (data.contact && data.contact.pushName) || null,
      message_type: messageType,
      session_id: body.sessionId
    }
  }
}];

const rows = $input.all().map(item => item.json).filter(r => r && r.message_id);
const currentMessageId = $('Validate Input + Build Envelope').item.json.current_message_id;

if (!rows.length) {
  return [{ json: { should_process: false, reason: 'queue_empty', rows: [] } }];
}

// Solo la ejecucion que trajo el ULTIMO mensaje pendiente se queda con el lote.
// Las anteriores se retiran: su contenido ya viaja dentro de este mismo batch.
const latest = rows[rows.length - 1];
const isOwner = latest.message_id === currentMessageId;

return [{
  json: {
    should_process: isOwner,
    reason: isOwner ? 'latest_message' : 'superseded_by_newer_message',
    current_message_id: currentMessageId,
    latest_message_id: latest.message_id,
    rows
  }
}];

const rows = $('Check Latest Batch Owner').item.json.rows || [];
const base = $('Validate Input + Build Envelope').item.json.envelope;

const messages = [];
const attachments = [];
const messageIds = [];
let pushName = base.channel.push_name;

for (const row of rows) {
  if (row.message_id) messageIds.push(row.message_id);
  if (row.message_text && String(row.message_text).trim()) {
    messages.push(String(row.message_text).trim());
  }
  if (Array.isArray(row.attachments)) {
    attachments.push(...row.attachments.filter(Boolean));
  }
  // El pushName mas reciente gana: la persona pudo cambiarlo entre mensajes.
  if (row.push_name) pushName = row.push_name;
}

const text = messages.join('\n').trim();

const envelope = {
  ...base,
  channel: { ...base.channel, push_name: pushName },
  message: {
    ...base.message,
    text,
    attachments,
    multimedia_text: '',
    combined_text: text
  },
  batch: {
    message_ids: messageIds,
    message_count: messageIds.length
  }
};

return [{
  json: {
    ...$('Validate Input + Build Envelope').item.json,
    envelope,
    batch_message_ids: messageIds,
    batch_id: `${base.channel.chat_id}:${messageIds.join('|')}`,
    has_attachments: attachments.length > 0
  }
}];

const raw = $json || {};
const parent = $('Merge Queued Messages').item.json;
const channel = parent.envelope.channel;

const mode = raw.mode === 'reply' ? 'reply' : 'no_reply';
const text = String(raw.text || '').trim();

if (mode === 'reply' && !text) {
  throw new Error('Fachada devolvio mode=reply sin texto');
}

// chat_id y session_id se toman del envelope PADRE, nunca de lo que devuelve
// la fachada. Con esos dos valores se manda un WhatsApp real: si la fachada
// devolviera un chat_id distinto, el mensaje le llegaria a otra persona.
return [{
  json: {
    client: 'convites',
    workflow_version: parent.workflow_version,
    chat_id: channel.chat_id,
    session_id: channel.session_id,
    idempotency_key: parent.idempotency_key,
    batch_id: parent.batch_id,
    batch_message_ids: parent.batch_message_ids,
    mode,
    text,
    requires_human: raw.requires_human === true,
    motivo: String(raw.motivo || '').trim(),
    push_name: channel.push_name || null,
    texto_ciudadano: String(parent.envelope.message.combined_text || '').trim(),
    outcome: mode === 'reply' ? 'success' : 'no_reply'
  }
}];

const parent = $('Validate Facade Output').first().json;

const MAX_CHUNKS = 3;   // cada bloque es una notificacion en el telefono de alguien
const MAX_CHARS  = 600; // arriba de esto WhatsApp se lee como ladrillo

// El corte lo decide el agente con lineas en blanco, no una heuristica que
// adivina donde termina una idea. Ver "Como se manda tu respuesta" en el prompt.
let parts = String(parent.text || '')
  .split(/\n\s*\n/)
  .map(s => s.trim())
  .filter(Boolean);

if (!parts.length) parts = [String(parent.text || '').trim()].filter(Boolean);
if (!parts.length) throw new Error('Split Reply Into Chunks: no hay texto para enviar');

// Un bloque que se paso de largo igual se parte, pero por final de oracion.
const split = [];
for (const part of parts) {
  if (part.length <= MAX_CHARS) { split.push(part); continue; }
  let buf = '';
  for (const sentence of part.split(/(?<=[.!?])\s+/)) {
    const merged = (buf + ' ' + sentence).trim();
    if (merged.length > MAX_CHARS && buf) { split.push(buf.trim()); buf = sentence; }
    else buf = merged;
  }
  if (buf.trim()) split.push(buf.trim());
}

// Tope duro. Mejor un ultimo bloque largo que ocho notificaciones seguidas.
const chunks = split.length > MAX_CHUNKS
  ? [...split.slice(0, MAX_CHUNKS - 1), split.slice(MAX_CHUNKS - 1).join('\n\n')]
  : split;

return chunks.map((chunk, i) => ({
  json: {
    chat_id: parent.chat_id,
    session_id: parent.session_id,
    idempotency_key: parent.idempotency_key,
    chunk,
    chunk_index: i + 1,
    chunk_total: chunks.length
  }
}));

const raw = $('When Executed by Another Workflow').item.json.body.data || {};
const base = $('Validate Input + Build Envelope').item.json;
const media = raw.media || {};

// El base64 se lee del webhook crudo y NO del envelope, para que no quede
// copiado en la salida de cada nodo de la cola.
return [{
  json: {
    client: 'convites',
    message_id: base.current_message_id,
    chat_id: base.envelope.channel.chat_id,
    media_type: raw.type || '',
    mimetype: media.mimetype || '',
    media_base64: media.data || ''
  }
}];

const base = $('Validate Input + Build Envelope').item.json;
const media = $json || {};

const transcripcion = String(media.text || '').trim();
const original = String(base.envelope.message.text || '').trim();

// La transcripcion se marca para que la fachada sepa que eso no lo escribio
// la persona: lo dijo. Si el agente lo cita literal, que se entienda.
const etiqueta = media.kind === 'voice' ? 'nota de voz' : media.kind === 'image' ? 'imagen' : 'archivo';
const bloque = transcripcion ? `[${etiqueta}] ${transcripcion}` : '';

const texto = [original, bloque].filter(Boolean).join('\n').trim();

if (!texto) {
  throw new Error('Merge Media Into Text: no quedo texto ni transcripcion');
}

const envelope = JSON.parse(JSON.stringify(base.envelope));
envelope.message.text = texto;
envelope.message.combined_text = texto;
envelope.message.multimedia_text = bloque;

return [{
  json: {
    ...base,
    envelope,
    queue_item: { ...base.queue_item, text: texto },
    media_ok: media.ok === true,
    media_kind: media.kind || null
  }
}];

// Los nodos Postgres reemplazan el item con el resultado de la query, asi
// que despues de `Read Bot State` el item es {esta_pausado:false} y el
// envelope se perdio. Este nodo lo devuelve a la cadena.
//
// Sin esto la fachada recibe un item sin texto y tira "batch sin texto",
// un error que ademas apunta al lugar equivocado: el batch SI tenia texto.
return [{ json: $('Merge Queued Messages').item.json }];

// Grupo del equipo "Convites — handoffs".
const DESTINO = '120363413066793404@g.us';

const v = $('Validate Facade Output').first().json;

const recorte = (s, n) => {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};

// Solo si el chat_id es número real (...@c.us). Con @lid no hay celular usable.
function celularDesdeChatId(chatId) {
  const id = String(chatId || '').trim();
  const m = id.match(/^(\d+)@c\.us$/i);
  return m ? m[1] : null;
}

const celular = celularDesdeChatId(v.chat_id);
const quien = celular
  ? `${v.push_name || 'sin nombre'} · ${celular}`
  : (v.push_name || 'sin nombre');

// El aviso tiene que alcanzar para actuar SIN abrir n8n ni la base.
const texto = [
  'Alguien necesita ayuda en el WhatsApp de Convites.',
  '',
  `De: ${quien}`,
  `Motivo: ${v.motivo}`,
  '',
  'Escribio:',
  `"${recorte(v.texto_ciudadano, 300)}"`,
  '',
  'Le respondimos:',
  `"${recorte(v.text, 200)}"`,
  '',
  celular
    ? 'Buscalo en WhatsApp por el numero (al lado del nombre) y seguile la conversacion.'
    : 'Buscalo en WhatsApp por el nombre y seguile la conversacion.',
  'Apenas escribas desde el telefono de Convites, el bot se aparta solo de ese chat.'
].join('\n');

return [{ json: { destino: DESTINO, texto, chat_ciudadano: v.chat_id, session_id: v.session_id, celular } }];
